use xiom.io;
use xiom.iter;
fn print_all[T](v: Vec[T]) {
  for __i in range(0, v.len()) {
    let item = v[__i];
    io.println(item.to_str()); }
}

fn main() -> Int {
  let bools: Vec[Bool] = Vec[Bool].new();
  bools.push(true); bools.push(false); bools.push(true);

  let floats: Vec[Float64] = Vec[Float64].new();
  floats.push(1.5); floats.push(2.5); floats.push(3.5);

  io.println(bools.len().to_str());
  io.println(floats.len().to_str());

  print_all(bools);
  print_all(floats);
  return 0;
}
